  FolderUtils: "resource:///modules/FolderUtils.sys.mjs",
  repairMbox: "resource:///modules/MboxRepair.sys.mjs",
  VirtualFolderHelper: "resource:///modules/VirtualFolderWrapper.sys.mjs",
});
